import React, { useState } from "react";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
const handleGoogleSignIn = () => {
  google.accounts.id.initialize({
    client_id: "284794061832-3cp9tbidnnp24obbtma1u17koe8oja5t.apps.googleusercontent.com",
    callback: handleGoogleResponse,
  });

  google.accounts.id.prompt(); 
};

const handleGoogleResponse = (response) => {
  // JWT token
  console.log("Google JWT Token:", response.credential);

  // Optional: decode token
  const user = JSON.parse(atob(response.credential.split('.')[1]));
  console.log("User:", user);

  alert("Google Sign-in Successful: " + user.email);
};








  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Email:", email);
    console.log("Password:", password);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white w-full max-w-sm p-6 rounded-xl shadow-md">
        <h2 className="text-2xl font-semibold text-center mb-6">Login</h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full border rounded-lg p-3 focus:outline-none focus:border-blue-500"
          />

          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full border rounded-lg p-3 focus:outline-none focus:border-blue-500"
          />

          <button
            type="submit"
            className="w-full bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700"
          >
            Login
          </button>
        </form>

        <button
  onClick={handleGoogleSignIn}
  className="w-full mt-4 flex items-center justify-center gap-2 border py-2 rounded-lg hover:bg-gray-50"
>
  <img
    src="https://www.svgrepo.com/show/475656/google-color.svg"
    alt="Google"
    className="w-5 h-5"
  />
  Sign in with Google
</button>

      </div>
    </div>
  );
}
